def hook(ctx, nb):
    if ctx.action.tool == "click_action" and ctx.action.value and ctx.action.value.lower() == "buy now":
        if ctx.predicates.product_price_over_budget:
            return {"kind": "block_and_prompt", "message": "The product price is over your budget. Please go back to search for a cheaper product."}
        missing = []
        try:
            if ctx.task.required_color:
                if ctx.webshop.selected_attributes.get("color") != ctx.task.required_color:
                    missing.append("color: " + ctx.task.required_color)
        except Exception:
            pass
        try:
            if ctx.task.required_size:
                if ctx.webshop.selected_attributes.get("size") != ctx.task.required_size:
                    missing.append("size: " + ctx.task.required_size)
        except Exception:
            pass
        try:
            if ctx.task.required_material:
                if ctx.webshop.selected_attributes.get("material") != ctx.task.required_material:
                    missing.append("material: " + ctx.task.required_material)
        except Exception:
            pass
        if missing:
            msg = "Missing required options: " + ", ".join(missing) + ". Please select them before buying."
            return {"kind": "block_and_prompt", "message": msg}
    return None
